import{_ as e,a0 as a,w as u,s as r,ao as p,I as t,x as o,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"SonoBus：支持跨平台的開源點對點音頻流應用 | LCTT x X-CMD","titleTemplate":false,"description":"SonoBus：支持跨平台的開源點對點音頻流應用 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"SonoBus：支持跨平台的開源點對點音頻流應用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"SonoBus：支持跨平台的開源點對點音頻流應用 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210511 SonoBus- An Open Source Peer-to-Peer Audio Streaming App with Cross-Platform Support","title":"SonoBus：支持跨平台的開源點對點音頻流應用","tag":"202105","desc":""},"relativePath":"202105/20210511 SonoBus- An Open Source Peer-to-Peer Audio Streaming App with Cross-Platform Support.md","filePath":"[post].md"}'),d={name:"202105/20210511 SonoBus- An Open Source Peer-to-Peer Audio Streaming App with Cross-Platform Support.md"};function m(f,s,b,g,S,T){const n=a("Link");return u(),r("div",null,[s[21]||(s[21]=p('<h1 id="sonobus-支持跨平台的開源點對點音頻流應用" tabindex="-1">SonoBus：支持跨平台的開源點對點音頻流應用 <a class="header-anchor" href="#sonobus-支持跨平台的開源點對點音頻流應用" aria-label="Permalink to “SonoBus：支持跨平台的開源點對點音頻流應用”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202105/19/122610n5qgu4443jf4nf4k.jpg" alt=""></p><blockquote><p>一個有趣的開源點對點音頻流應用，它提供了一個簡單的用户界面和強大的功能。</p></blockquote><h3 id="sonobus-跨平台音頻流應用" tabindex="-1">SonoBus: 跨平台音頻流應用 <a class="header-anchor" href="#sonobus-跨平台音頻流應用" aria-label="Permalink to “SonoBus: 跨平台音頻流應用”">​</a></h3><p>如今，音頻流服務在聽音樂時非常受歡迎。然而，本地音樂集仍然是一種有用的方式，這不需要一直連接到互聯網。</p><p>儘管流媒體音樂服務很方便，但你並不真正擁有這些音樂。因此，如果出現許可問題，該平台可能會刪除你最喜歡的音樂，而你對此無能為力。</p><p>而有了本地音樂音樂集，你就不會遇到這個問題了。但是，你如何通過設備網絡串流你本地的音樂，或者與一個小組分享？</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/sonobus-screenshot.png?resize=800%2C605&amp;ssl=1" alt=""></p><p>SonoBus 可以成為解決這個問題的辦法。不僅僅限於音樂，還包括任何音頻，如與一羣朋友遠程練習音樂或合作製作音樂，為什麼不呢？</p><p>讓我們來看看它提供了什麼。</p><h3 id="sonobus-的功能" tabindex="-1">SonoBus 的功能 <a class="header-anchor" href="#sonobus-的功能" aria-label="Permalink to “SonoBus 的功能”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/sonus-screenshot-1.png?resize=800%2C619&amp;ssl=1" alt=""></p><p>SonoBus 使用起來比較簡單，但提供的功能可能會讓人震驚。因此，在繼續使用之前，你可能想先知道它能讓你做什麼：</p><ul><li>能夠連接到多個用户</li><li>創建一個有可選密碼的小組</li><li>分享來自你的麥克風的音頻輸入</li><li>分享來自文件的音頻流</li><li>支持單聲道/立體聲</li><li>組內播放</li><li>錄製所有人的音頻</li><li>能夠使個別用户或所有人都靜音</li><li>可以通過互聯網或本地網絡連接</li><li>支持節拍器，用於協作製作音樂或遠程練習課程</li><li>支持高質量的音頻，最高可達 256Kbps</li><li>輸入混音器</li><li>支持聲相</li><li>支持有用的效果器（噪聲門、壓縮器和均衡器）</li><li>可在 JACK 和 ALSA 下工作</li><li>跨平台支持（Windows、macOS、Android、iOS 和 Linux）</li></ul><p>雖然我試圖提到所有的基本功能，但你可以在效果器的幫助下得到非常多的控制，來調整音量、質量、延遲，以及音頻效果。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/sonobus-official.png?resize=800%2C545&amp;ssl=1" alt=""></p><p>它最好的一點是<strong>跨平台支持</strong>，這使它成為任何用户羣的有趣選擇，而無論你出於什麼原因要串流音頻。</p><h3 id="在-linux-中安裝-sonobus" tabindex="-1">在 Linux 中安裝 SonoBus <a class="header-anchor" href="#在-linux-中安裝-sonobus" aria-label="Permalink to “在 Linux 中安裝 SonoBus”">​</a></h3>',18)),t("p",null,[s[2]||(s[2]=o("無論你使用什麼 Linux 發行版，你都可以輕鬆地安裝 ",-1)),l(n,{href:"https://snapcraft.io/sonobus"},{default:i(()=>[...s[0]||(s[0]=[o("Snap 包",-1)])]),_:1}),s[3]||(s[3]=o("或 ",-1)),l(n,{href:"https://flathub.org/apps/details/net.sonobus.SonoBus"},{default:i(()=>[...s[1]||(s[1]=[o("Flatpak 包",-1)])]),_:1}),s[4]||(s[4]=o("。如果你不想使用它們，你可以手動添加官方倉庫來安裝：",-1))]),s[22]||(s[22]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;deb http://pkg.sonobus.net/apt stable main&quot; | sudo tee /etc/apt/sources.list.d/sonobus.list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo wget -O /etc/apt/trusted.gpg.d/sonobus.gpg https://pkg.sonobus.net/apt/keyring.gpg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo apt update &amp;&amp; sudo apt install sonobus</span></span></code></pre></div><p>你也可以通過其官方網站為你喜歡的平台下載它。</p>`,2)),t("ul",null,[t("li",null,[l(n,{href:"https://sonobus.net/"},{default:i(()=>[...s[5]||(s[5]=[o("SonoBus",-1)])]),_:1})])]),s[23]||(s[23]=t("h3",{id:"總結",tabindex:"-1"},[o("總結 "),t("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),s[24]||(s[24]=t("p",null,"SonoBus 是一個令人印象深刻的音頻流應用，有很多潛在的用途，但它也有一些問題，可能不是每個人的完美解決方案。",-1)),s[25]||(s[25]=t("p",null,"例如，我注意到桌面應用佔用大量的系統資源，所以這對較舊的系統來説可能是個問題。",-1)),s[26]||(s[26]=t("p",null,"另外，Play Store 上的安卓應用仍處於早期訪問階段（測試版）。在我的快速測試中，它工作符合預期，但我已經很久沒有使用它了。因此，當依靠它進行跨平台會話時，可能會出現預期的小問題。",-1)),s[27]||(s[27]=t("p",null,"在任何情況下，它都適用於每種用例的大量功能。如果你還沒有使用過，請試一試。",-1)),s[28]||(s[28]=t("hr",null,null,-1)),t("p",null,[s[7]||(s[7]=o("via: ",-1)),l(n,{href:"https://itsfoss.com/sonobus/"},{default:i(()=>[...s[6]||(s[6]=[o("https://itsfoss.com/sonobus/",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=o("作者：",-1)),l(n,{href:"https://itsfoss.com/author/ankush/"},{default:i(()=>[...s[8]||(s[8]=[o("Ankush Das",-1)])]),_:1}),s[13]||(s[13]=o(" 選題：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[9]||(s[9]=[o("lujun9972",-1)])]),_:1}),s[14]||(s[14]=o(" 譯者：",-1)),l(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[10]||(s[10]=[o("geekpi",-1)])]),_:1}),s[15]||(s[15]=o(" 校對：",-1)),l(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[11]||(s[11]=[o("wxy",-1)])]),_:1})]),t("p",null,[s[18]||(s[18]=o("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[16]||(s[16]=[o("LCTT",-1)])]),_:1}),s[19]||(s[19]=o(" 原創編譯，",-1)),l(n,{href:"https://linux.cn/"},{default:i(()=>[...s[17]||(s[17]=[o("Linux中國",-1)])]),_:1}),s[20]||(s[20]=o(" 榮譽推出",-1))])])}const x=e(d,[["render",m]]);export{C as __pageData,x as default};
